/* build_mew_bundle.js — a small browser bundle of self-play games for the MEW booth.
 *
 * The full self-play store is unbounded by design, so the site must never load it. This takes a
 * handful of games, strips them to what the viewer draws, and writes data/mew.js.
 *
 * GENERATED FILE. Do not hand-edit data/mew.js.
 *   node build/build_mew_bundle.js [count]
 */
'use strict';
const fs = require('fs');
const path = require('path');
const ROOT = path.join(__dirname, '..');
const D = (...p) => path.join(ROOT, ...p);

const N = parseInt(process.argv[2] || '12', 10);
const SRC = D('data', 'games.selfplay.jsonl');
if (!fs.existsSync(SRC)) { console.error(`no self-play store at ${SRC}; run engine/mew.js first`); process.exit(1); }

const all = [];
for (const line of fs.readFileSync(SRC, 'utf8').split('\n')) {
  const t = line.trim(); if (!t) continue;
  try { all.push(JSON.parse(t)); } catch { /* skip */ }
}
if (!all.length) { console.error('self-play store is empty'); process.exit(1); }

/* Prefer games with some length — a 2-turn game shows nothing about what MEW does. */
const ranked = all.slice().sort((a, b) => (b.turns || []).length - (a.turns || []).length);
const picked = ranked.slice(0, N);

const slim = picked.map(g => ({
  id: g.id,
  winner: g.winner,
  policy: (g.selfplay || {}).policy || 'unknown',
  seed: (g.selfplay || {}).seed,
  six: g.six,
  brought: g.brought,
  lead: g.lead,
  sets: g.sets,
  // only the fields the viewer draws, and only real events
  turns: (g.turns || []).map(t => ({
    n: t.n,
    ev: (t.ev || []).filter(e => ['m', 'd', 'f', 's', 'w', 'mega'].includes(e.t)),
  })),
}));

const meta = {
  generated: new Date().toISOString().slice(0, 10),
  engine_commit: (picked[0].selfplay || {}).engine_commit || null,
  format: (picked[0].selfplay || {}).format || null,
  total_selfplay_games: all.length,
  shown: slim.length,
};

const out =
  `/* data/mew.js — GENERATED by build/build_mew_bundle.js. Do not hand-edit.\n` +
  ` * A small sample of MEW self-play games for the browser viewer. The full self-play store is\n` +
  ` * unbounded and must never be loaded by the site. */\n` +
  `window.MEW = ${JSON.stringify({ meta, games: slim })};\n`;

fs.writeFileSync(D('data', 'mew.js'), out);
console.log(`wrote data/mew.js — ${slim.length} of ${all.length} games, ${(out.length / 1024).toFixed(0)} KB`);
